class ProcessSighting[Status](ABC):
    """A thread's live presence, answering for the process state its owner has."""

    __slots__ = ()

    @abstractmethod
    def heartbeat_seen(self, last_seen: float) -> Status:
        """The presence when no process is recorded: the heartbeat is the evidence."""

    @abstractmethod
    def process_seen(self, process: ProcessState) -> Status:
        """The presence when a process is recorded for it."""


class ProcessFence[Status](ABC):
    """A stored stop, answering for whether a process still binds it."""

    __slots__ = ()

    @abstractmethod
    def unbound(self) -> Status:
        """The stop when no process binds it."""

    @abstractmethod
    def fenced(self) -> Status:
        """The stop while its process still binds it."""


class NativeBinding[Presentation](ABC):
    """A registry lease that presents its thread natively once a process holds it."""

    __slots__ = ()

    @abstractmethod
    def native_presentation(self, ordinary: Presentation) -> Presentation: ...


class ProcessRestart[Change](ABC):
    """A registration change over a prior incarnation, kept or restarted by its processes."""

    __slots__ = ()

    @property
    @abstractmethod
    def previous_incarnation(self) -> ThreadIncarnation: ...

    @abstractmethod
    def kept(self) -> Change:
        """The change as requested: no process restarts it."""

    @abstractmethod
    def restarted(self) -> Change:
        """The change once a process replaces the prior incarnation's."""


class ProcessState(SubclassUnion, affix=""):
    """An exact recorded process or a worker which has never started."""

    @abstractmethod
    def allows_owner_start(self) -> bool: ...

    def require_owner_startable(self) -> None:
        """Refuse if the process state does not allow starting an owner."""
        if not self.allows_owner_start():
            raise RelationViolationError('Retired session acquired another process')
    @abstractmethod
    def allows_inactive_stop(self) -> bool: ...

    @abstractmethod
    def require_held_by(self, role: type[ThreadRole]) -> None: ...
    @abstractmethod
    def conflicts_with(self, previous: ProcessState) -> bool: ...

    @abstractmethod
    def registration_change[Change](
        self, previous: ProcessState, change: ProcessRestart[Change], incarnation: ThreadIncarnation,
    ) -> Change: ...

    @abstractmethod
    def restarted_registration[Change](
        self, change: ProcessRestart[Change], incarnation: ThreadIncarnation,
    ) -> Change: ...

    @abstractmethod
    def native_presentation[Presentation](
        self, ordinary: Presentation, binding: NativeBinding[Presentation],
    ) -> Presentation: ...

    @abstractmethod
    def applied(self, previous: ProcessState) -> ProcessState: ...

    @abstractmethod
    def offline(self) -> bool: ...

    @abstractmethod
    def require(self, message: str = "No worker process has started") -> ProcessIdentity: ...

    @abstractmethod
    def alive(self) -> bool: ...

    @abstractmethod
    def thread_status[Status](self, presence: ProcessSighting[Status], last_seen: float) -> Status: ...

    @abstractmethod
    def stopped_seen[Status](self, stopped: ProcessFence[Status]) -> Status:
        """A stored stop with no process is stopped; one still bound is a fence."""

    @abstractmethod
    def runs_here(self) -> bool: ...

    @abstractmethod
    def signal(self, signum: int) -> None: ...

    @abstractmethod
    def require_release_by(self, process: ProcessIdentity) -> None: ...

    @abstractmethod
    def held_external_stop(self, release: Callable[[], None], name: str) -> str | None:
        """Stop a CLI endpoint this process holds: the name still for the ordinary stop, if any."""


@dataclass(frozen=True)
class NoProcess(NullMember, ProcessState):
    def allows_owner_start(self) -> bool:
        return True

    def allows_inactive_stop(self) -> bool:
        return True

    def require_held_by(self, role: type[ThreadRole]) -> None:
        """No process is held, so any role may declare it."""

    def conflicts_with(self, previous: ProcessState) -> bool:
        return False

    def registration_change[Change](
        self, previous: ProcessState, change: ProcessRestart[Change], incarnation: ThreadIncarnation,
    ) -> Change:
        return change.kept()

    def restarted_registration[Change](
        self, change: ProcessRestart[Change], incarnation: ThreadIncarnation,
    ) -> Change:
        return change.kept()

    def native_presentation[Presentation](
        self, ordinary: Presentation, binding: NativeBinding[Presentation],
    ) -> Presentation:
        return ordinary

    def applied(self, previous: ProcessState) -> ProcessState:
        return previous

    def offline(self) -> bool:
        return False

    def require(self, message: str = "No worker process has started") -> ProcessIdentity:
        raise RelationViolationError(message)

    def alive(self) -> bool:
        return False

    def thread_status[Status](self, presence: ProcessSighting[Status], last_seen: float) -> Status:
        return presence.heartbeat_seen(last_seen)

    def stopped_seen[Status](self, stopped: ProcessFence[Status]) -> Status:
        return stopped.unbound()

    def runs_here(self) -> bool:
        return False

    def signal(self, signum: int) -> None:
        pass

    def require_release_by(self, process: ProcessIdentity) -> None:
        # Stopping before the first start still produces a valid release.
        pass

    def held_external_stop(self, release: Callable[[], None], name: str) -> str | None:
        """Nothing holds the endpoint, so the ordinary stop finishes it on the bus."""
        return name


@dataclass(frozen=True)
class ProcessIdentity(RecordMember, ProcessState):
    pid: int
    start_time: int

    def __post_init__(self) -> None:
        if self.pid <= 0 or self.start_time <= 0:
            raise ValueError("A positive PID and platform start time are required")

    def memory(self, proc: Path = Path("/proc")) -> ResidentMemory:
        platform = Platform.current()
        platform.require(self)
        result = ResidentMemory.read(proc / str(self.pid))
        platform.require(self)
        return result

    @classmethod
    def pid_argument(cls, value: str) -> dict[str, object]:
        return FieldCodec.encode_record(cls.capture(int(value)))

    @classmethod
    def capture(cls, pid: int) -> ProcessIdentity:
        return cls.current() if pid == os.getpid() else Platform.current().identity(pid)

    @classmethod
    def current(cls) -> ProcessIdentity:
        """The caller's immutable birth; a fork selects its own PID, not its parent's."""
        return cls._current(os.getpid())

    @staticmethod
    @cache
    def _current(pid: int) -> ProcessIdentity:
        return Platform.current().identity(pid)

    def allows_owner_start(self) -> bool:
        return False

    def allows_inactive_stop(self) -> bool:
        return self.runs_here()

    def require_held_by(self, role: type[ThreadRole]) -> None:
        role.require_executable(
            RelationViolationError("A human thread cannot hold an owner process")
        )

    def conflicts_with(self, previous: ProcessState) -> bool:
        return self != previous

    def offline(self) -> bool:
        return not self.alive()

    def native_presentation[Presentation](
        self, ordinary: Presentation, binding: NativeBinding[Presentation],
    ) -> Presentation:
        return binding.native_presentation(ordinary)

    def applied(self, previous: ProcessState) -> ProcessState:
        return self

    def require(self, message: str = "No worker process has started") -> ProcessIdentity:
        return self

    @staticmethod
    def in_group(pid: int, start_time: int, pgid: int) -> ProcessIdentity:
        return GroupLeader(pid, start_time) if pgid == pid else GroupMember(pid, start_time)

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, ProcessIdentity):
            return NotImplemented
        return (self.pid, self.start_time) == (other.pid, other.start_time)

    def alive(self) -> bool:
        return Platform.current().matches(self)

    def arguments(self) -> tuple[str, ...]:
        return Platform.current().arguments(self)

    def environment(self) -> dict[str, str]:
        return Platform.current().environment(self)

    def require_alive(self) -> ProcessIdentity:
        """Validate this recorded PID and start time against the live process."""
        return Platform.current().require(self)

    def runs_here(self) -> bool:
        return os.getpid() == self.pid

    def signal(self, signum: int) -> None:
        Platform.current().send(self, signum)

    def lineage(self) -> Iterator[ProcessIdentity]:
        """This incarnation and its exact ancestors, ending at PID 1."""
        platform = Platform.current()
        current = self
        while True:
            yield current
            if current.pid == 1:
                return
            current = platform.parent_identity(current.pid)

    def require_ancestor_of(self, pid: int) -> None:
        """A supplied process is authority only for its actual descendant."""
        platform = Platform.current()
        platform.require(self)
        if self in platform.identity(pid).lineage():
            return
        raise IdentityMismatchError('The declared process is not an ancestor of this hook')

    async def wait_exited(self) -> None:
        await Platform.current().wait_exited(self)

    def require_release_by(self, process: ProcessIdentity) -> None:
        if self != process:
            raise RelationViolationError("Only the registered owner may release itself.")

    def held_external_stop(self, release: Callable[[], None], name: str) -> str | None:
        """A live holder (a CLI bridge or the connector's inbox watch) serves no owner runtime to
        retire, so its binding is released for it. A dead holder left a binding the ordinary stop
        finishes."""
        if not self.alive():
            return name
        release()
        return None

    def thread_status[Status](self, presence: ProcessSighting[Status], last_seen: float) -> Status:
        return presence.process_seen(self)

    def stopped_seen[Status](self, stopped: ProcessFence[Status]) -> Status:
        return stopped.fenced()

    def registration_change[Change](
        self, previous: ProcessState, change: ProcessRestart[Change], incarnation: ThreadIncarnation,
    ) -> Change:
        return previous.restarted_registration(change, incarnation)

    def restarted_registration[Change](
        self, change: ProcessRestart[Change], incarnation: ThreadIncarnation,
    ) -> Change:
        return change.restarted() if incarnation != change.previous_incarnation else change.kept()

    def members(self, platform: Platform) -> tuple[ProcessIdentity, ...]:
        return ()  # A stored, exited identity cannot grant group ownership.


NO_PROCESS = NoProcess()


class GroupLeader(ProcessIdentity, declared_name=None):
    def members(self, platform: Platform) -> tuple[ProcessIdentity, ...]:
        return tuple(member for member in platform.members_of_group(self.pid)
                     if member.start_time >= self.start_time)


class GroupMember(ProcessIdentity, declared_name=None):
    def members(self, platform: Platform) -> tuple[ProcessIdentity, ...]:
        return (self,) if platform.matches(self) else ()


