class PidfdHandles:
    @staticmethod
    def open_pidfd(pid: int) -> int:
        """Use libc when a portable Python build omitted Linux wrappers."""
        if hasattr(os, "pidfd_open"):
            return os.pidfd_open(pid)
        libc = ctypes.CDLL(None, use_errno=True)
        function = getattr(libc, "pidfd_open", None)
        if function is None:
            raise NotImplementedError("Linux libc pidfd_open unavailable")
        function.argtypes = (ctypes.c_int, ctypes.c_uint)
        function.restype = ctypes.c_int
        descriptor = function(pid, 0)
        if descriptor < 0:
            code = ctypes.get_errno()
            raise OSError(code, os.strerror(code))
        return int(descriptor)

    @staticmethod
    def signal_pidfd(pidfd: int, sig: int) -> None:
        if hasattr(signal, "pidfd_send_signal"):
            signal.pidfd_send_signal(pidfd, sig)
            return
        libc = ctypes.CDLL(None, use_errno=True)
        function = getattr(libc, "pidfd_send_signal", None)
        if function is None:
            raise NotImplementedError("Linux libc pidfd_send_signal unavailable")
        function.argtypes = (ctypes.c_int, ctypes.c_int, ctypes.c_void_p, ctypes.c_uint)
        function.restype = ctypes.c_int
        if function(pidfd, sig, None, 0) < 0:
            code = ctypes.get_errno()
            raise OSError(code, os.strerror(code))


class Platform(DeclaredFamily, affix="Platform"):
    store_lock_interval = 0.025
    store_lock_first_wait = 0.0002

    @classmethod
    def store_lock_waits(cls) -> Iterator[float]:
        """How long each refused attempt at a store lock waits before the next: short at first,
        doubling up to the interval. A commit holds a store lock for about a millisecond, so a
        reader that slept the whole interval after one refusal waited 25 ms for a lock that was
        free in one: 0.59 s of a channel message's wall time in the worker alone."""
        wait = cls.store_lock_first_wait
        while True:
            yield wait
            wait = min(wait * 2, cls.store_lock_interval)

    @classmethod
    def current(cls) -> Platform:
        return cls.member_named(sys.platform)()

    def sync_file(self, path: Path) -> None:
        descriptor = os.open(path, os.O_RDONLY)
        try:
            os.fsync(descriptor)
        finally:
            os.close(descriptor)

    def sync_directory(self, path: Path) -> None:
        descriptor = os.open(path, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
        try:
            os.fsync(descriptor)
        finally:
            os.close(descriptor)

    class NativeImage(ctypes.Structure):
        """The POSIX loader's native symbol-image ABI."""

        _fields_ = (
            ("filename", ctypes.c_char_p),
            ("base", ctypes.c_void_p),
            ("symbol", ctypes.c_char_p),
            ("address", ctypes.c_void_p),
        )

    @contextmanager
    def native_image(self, address: ctypes.c_void_p) -> Generator[BufferedReader]:
        """Open the native file providing a symbol; the caller consumes this handle."""
        lookup = ctypes.CDLL(None).dladdr
        lookup.argtypes = (ctypes.c_void_p, ctypes.POINTER(self.NativeImage))
        lookup.restype = ctypes.c_int
        image = self.NativeImage()
        if not lookup(address, ctypes.byref(image)) or not image.filename:
            raise ValueError("The loader did not identify the native symbol image")
        with Path(os.fsdecode(image.filename)).resolve(strict=True).open("rb") as stream:
            yield stream

    @abstractmethod
    def require_watched_procfs(self, refusal: Exception) -> None: ...

    def is_private(self, info: os.stat_result, permissions: int) -> bool:
        return stat.S_IMODE(info.st_mode) == permissions and self.is_owned(info)

    def is_owned(self, info: os.stat_result) -> bool:
        return info.st_uid == os.geteuid()

    def trusted_ancestor_owner(self, uid: int) -> bool:
        return uid in (0, os.geteuid())

    def ancestor_write_bits(self, info: os.stat_result) -> int:
        """Directory write permissions granted outside the owner's trusted principals."""
        return info.st_mode & 0o022

    def publish_new_file(
        self, staged: str | Path, destination: str | Path, *,
        src_dir_fd: int | None = None, dst_dir_fd: int | None = None,
    ) -> None:
        """Publish a closed stage without replacing a winner; the stage may be consumed."""
        os.link(staged, destination, src_dir_fd=src_dir_fd, dst_dir_fd=dst_dir_fd,
                follow_symlinks=False)

    def snapshot_file(
        self, source: str | Path, destination: str | Path, *,
        src_dir_fd: int | None = None, dst_dir_fd: int | None = None,
    ) -> None:
        """Retain an immutable file's bytes and mode under a new, exclusive name."""
        os.link(source, destination, src_dir_fd=src_dir_fd, dst_dir_fd=dst_dir_fd,
                follow_symlinks=False)

    def share_file(self, source: Path, destination: Path) -> bool:
        """Share an immutable artifact's inode, or report that no sharing occurred."""
        os.link(source, destination, follow_symlinks=False)
        return True

    def make_private(self, path: Path, permissions: int) -> None:
        with suppress(FileNotFoundError):
            if stat.S_IMODE(path.lstat().st_mode) != permissions:
                os.chmod(path, permissions, follow_symlinks=False)

    def make_private_descriptor(self, descriptor: int, permissions: int) -> None:
        if stat.S_IMODE(os.fstat(descriptor).st_mode) != permissions:
            os.fchmod(descriptor, permissions)

    @contextmanager
    def socket_address(self, path: Path, descriptor: int) -> Generator[Path]:
        with TemporaryDirectory(prefix="ac-socket-", dir="/tmp") as directory:
            parent = Path(directory) / "d"
            parent.symlink_to(path.parent, target_is_directory=True)
            if not os.path.samestat(os.stat(parent), os.fstat(descriptor)):
                raise ValueError("Socket directory changed during address acquisition")
            yield parent / path.name

    def launch(
        self, command: tuple[str, ...], pass_fds: tuple[int, ...], runtime: LaunchRuntime,
        lifetime: type[ChildLifetime],
    ) -> ChildLaunch:
        return ChildLaunch(self, command, pass_fds, runtime, lifetime)

    def terminate_group(self, identity: ProcessIdentity) -> None:
        self.signal_group(identity, signal.SIGTERM)

    def force_group(self, identity: ProcessIdentity) -> None:
        self.signal_group(identity, signal.SIGKILL)

    @abstractmethod
    def identity(self, pid: int) -> ProcessIdentity: ...

    def started_at(self, identity: ProcessIdentity) -> float:
        """This recorded process's birth on the monotonic clock."""
        raise NotImplementedError("This platform does not expose process elapsed time")

    @abstractmethod
    def arguments(self, process: ProcessIdentity) -> tuple[str, ...]: ...

    @abstractmethod
    def environment(self, process: ProcessIdentity) -> dict[str, str]: ...

    @abstractmethod
    def process_name(self, pid: int) -> str: ...

    def lock_holders(self, descriptor: int) -> tuple[LockHolder, ...]:
        return (UnidentifiedLockHolder(),)

    def parent_identity(self, pid: int) -> ProcessIdentity:
        raise NotImplementedError('This platform does not expose exact parent identities')

    async def wait_exited(self, identity: ProcessIdentity) -> None:
        """Wait for one incarnation's exit; members with a loop-readable handle override this."""
        await asyncio.to_thread(self.wait_any_exited, (identity,), math.inf)

    @abstractmethod
    def wait_any_exited(
        self, identities: tuple[ProcessIdentity, ...], timeout: float,
    ) -> None:
        """Wait for a member's exit or the caller's remaining deadline."""

    def matches(self, identity: ProcessIdentity) -> bool:
        if identity.runs_here():
            return identity == ProcessIdentity.current()
        try:
            return self.identity(identity.pid) == identity
        except ProcessLookupError:
            return False

    def require(self, identity: ProcessIdentity) -> ProcessIdentity:
        with suppress(ProcessLookupError):
            current = self.identity(identity.pid)
            if current == identity:
                return current
        raise IdentityMismatchError(f"Process incarnation changed: {identity.pid}")

    def send(self, identity: ProcessIdentity, signum: int) -> None:
        self.require(identity)
        os.kill(identity.pid, signum)

    def group_members(self, leader: ProcessIdentity) -> tuple[ProcessIdentity, ...]:
        try:
            current = self.identity(leader.pid)
        except ProcessLookupError:
            return leader.members(self)
        if current != leader:
            raise IdentityMismatchError(f"Process incarnation changed: {leader.pid}")
        return current.members(self)

    def signal_group(self, leader: ProcessIdentity, signum: int) -> None:
        # Snapshot identities, then signal each exact member. Never signal a
        # numeric group after its leader may have been reaped and reused.
        signalled = 0
        for member in self.group_members(leader):
            try:
                self.send(member, signum)
            except ProcessLookupError:
                continue
            signalled += 1
        if not signalled and self.matches(leader):
            raise RuntimeError(f"Live process {leader.pid} was not signalled")

    def parent_death_binding(self) -> int:
        """Darwin has no parent-death signal: its exec gate binds no launcher."""
        return 0

    @abstractmethod
    def members_of_group(self, pgid: int) -> tuple[ProcessIdentity, ...]: ...


@dataclass(frozen=True)
class LinuxProcessRecord:
    identity: ProcessIdentity
    group: int
    parent: int


class LinuxPlatform(PidfdHandles, Platform):
    @contextmanager
    def native_image(self, address: ctypes.c_void_p) -> Generator[BufferedReader]:
        # glibc's main-image filename aliases argv[0]; setproctitle changes it.
        # Resolve the actual symbol mapping instead, including shared libpython.
        # ctypes represents C null as None; kernel mapping addresses are integers.
        pointer = address.value or 0
        if pointer == 0:
            raise ValueError("A null address has no native image")
        with Path("/proc/self/maps").open() as mappings:
            for line in mappings:
                extent, _permissions, _offset, device, inode, *_name = line.split(maxsplit=5)
                first, stop = (int(value, 16) for value in extent.split("-"))
                if first <= pointer < stop:
                    link = Path("/proc/self/map_files") / f"{first:x}-{stop:x}"
                    with link.resolve(strict=True).open("rb") as stream:
                        observed = os.fstat(stream.fileno())
                        major, minor = (int(value, 16) for value in device.split(":"))
                        # Decode kernel metadata once at this native boundary.
                        if (observed.st_dev, observed.st_ino) != (os.makedev(major, minor), int(inode)):
                            raise ValueError("The native image file no longer matches its mapping")
                        yield stream
                    return
        raise ValueError("The kernel did not identify the native symbol image")

    def require_watched_procfs(self, refusal: Exception) -> None:
        return None

    @contextmanager
    def socket_address(self, path: Path, descriptor: int) -> Generator[Path]:
        yield Path(f"/proc/{os.getpid()}/fd/{descriptor}") / path.name

    def parent_death_binding(self) -> int:
        """The exec gate arms PR_SET_PDEATHSIG and binds to this launcher's PID."""
        return os.getpid()

    @staticmethod
    def _stat(pid: int) -> LinuxProcessRecord:
        """One process as the kernel has it now. A process changes group at exec and its PID
        is reused after it dies, so no earlier read answers for a later one."""
        try:
            # comm can contain whitespace and ')'; fields after its final ')'
            # start at field 3. Kernel starttime is field 22, pgrp is field 5.
            fields = Path(f"/proc/{pid}/stat").read_text().rsplit(") ", 1)[1].split()
        except FileNotFoundError:
            raise ProcessLookupError(pid) from None
        if fields[0] in {"Z", "X"}:
            raise ProcessLookupError(pid)
        group = int(fields[2])
        return LinuxProcessRecord(
            ProcessIdentity.in_group(pid, int(fields[19]), group), group, int(fields[1]))

    def identity(self, pid: int) -> ProcessIdentity:
        return self._stat(pid).identity

    def started_at(self, identity: ProcessIdentity) -> float:
        started = identity.start_time / os.sysconf("SC_CLK_TCK")
        age = time.clock_gettime(time.CLOCK_BOOTTIME) - started
        return time.monotonic() - age

    def arguments(self, process: ProcessIdentity) -> tuple[str, ...]:
        try:
            raw = Path(f"/proc/{process.pid}/cmdline").read_bytes()
        except FileNotFoundError:
            raise ProcessLookupError(process.pid) from None
        if not raw:
            raise ProcessLookupError(process.pid)
        return tuple(os.fsdecode(word) for word in raw.split(b"\0")[:-1])

    def environment(self, process: ProcessIdentity) -> dict[str, str]:
        try:
            raw = Path(f"/proc/{process.pid}/environ").read_bytes()
        except FileNotFoundError:
            raise ProcessLookupError(process.pid) from None
        values = (item.split(b"=", 1) for item in raw.split(b"\0") if b"=" in item)
        return {os.fsdecode(key): os.fsdecode(value) for key, value in values}

    def process_name(self, pid: int) -> str:
        try:
            return Path(f"/proc/{pid}/comm").read_text().strip()
        except FileNotFoundError:
            raise ProcessLookupError(pid) from None

    def lock_holders(self, descriptor: int) -> tuple[LockHolder, ...]:
        """Identify actual flock owners of this opened file, not merely open FDs.

        An OFD lock with no reported PID, inaccessible /proc, or a concurrent exit
        is unknown; absence never proves sole ownership of the lock.
        """
        info = os.fstat(descriptor)
        identity = f"{os.major(info.st_dev):02x}:{os.minor(info.st_dev):02x}:{info.st_ino}"
        holders = []
        with open('/proc/locks', encoding='ascii') as locks:
            for line in locks:
                fields = line.split()
                if len(fields) < 8 or fields[1] != 'FLOCK' or fields[5] != identity:
                    continue
                pid = int(fields[4])
                if pid < 0:
                    holders.append(UnidentifiedLockHolder())
                    continue
                try:
                    command = " ".join(self.arguments(self.identity(pid)))
                except ProcessLookupError:
                    holders.append(ExitedLockHolder(pid))
                else:
                    holders.append(RunningLockHolder(pid, command))
        return tuple(holders)

    def parent_identity(self, pid: int) -> ProcessIdentity:
        return self.identity(self._stat(pid).parent)

    async def wait_exited(self, identity: ProcessIdentity) -> None:
        try:
            descriptor = self.open_pidfd(identity.pid)
        except ProcessLookupError:
            return
        try:
            self.require(identity)
            loop = asyncio.get_running_loop()
            exited = loop.create_future()
            def observe() -> None:
                if not exited.done():
                    exited.set_result(None)
            loop.add_reader(descriptor, observe)
            try:
                await exited
            finally:
                loop.remove_reader(descriptor)
        except ProcessLookupError:
            return
        finally:
            os.close(descriptor)

    def wait_any_exited(
        self, identities: tuple[ProcessIdentity, ...], timeout: float,
    ) -> None:
        descriptors: list[int] = []
        try:
            pending = select.poll()
            for identity in identities:
                try:
                    descriptor = self.open_pidfd(identity.pid)
                    descriptors.append(descriptor)
                    current = self.identity(identity.pid)
                except ProcessLookupError:
                    return
                if current != identity:
                    return  # Another incarnation holds the pid: this member exited.
                pending.register(descriptor, select.POLLIN)
            pending.poll(None if math.isinf(timeout) else max(0, math.ceil(timeout * 1000)))
        finally:
            for descriptor in descriptors:
                os.close(descriptor)

    def members_of_group(self, pgid: int) -> tuple[ProcessIdentity, ...]:
        """The kernel answers an empty group in one call; only a live one walks /proc."""
        try:
            os.killpg(pgid, 0)
        except ProcessLookupError:
            return ()
        except PermissionError:
            pass
        members = []
        for entry in Path("/proc").iterdir():
            if entry.name.isdecimal():
                with suppress(ProcessLookupError):
                    record = self._stat(int(entry.name))
                    if record.group == pgid:
                        members.append(record.identity)
        return tuple(members)

    def send(self, identity: ProcessIdentity, signum: int) -> None:
        # Bind first; recheck start time against the pidfd-bound incarnation
        # before signaling. A concurrent exit can never target a reused PID.
        descriptor = self.open_pidfd(identity.pid)
        try:
            self.require(identity)
            self.signal_pidfd(descriptor, signum)
        finally:
            os.close(descriptor)


class AndroidPlatform(LinuxPlatform):
    """Termux's Python names Android; its process and file operations use the Linux kernel."""

    # AOSP's AID_SYSTEM owns /data; app UID/GID pairs own their isolated sandboxes.
    system_identity = 1000

    def trusted_ancestor_owner(self, uid: int) -> bool:
        return uid == self.system_identity or super().trusted_ancestor_owner(uid)

    def ancestor_write_bits(self, info: os.stat_result) -> int:
        writes = super().ancestor_write_bits(info)
        if info.st_gid in (0, self.system_identity, os.getegid()):
            writes &= ~0o020
        return writes

    def publish_new_file(
        self, staged: str | Path, destination: str | Path, *,
        src_dir_fd: int | None = None, dst_dir_fd: int | None = None,
    ) -> None:
        # Android forbids hard links. renameat2 supplies the same no-replace decision
        # without opening the published SQLite inode and releasing another fd's locks.
        function = ctypes.CDLL(None, use_errno=True).renameat2
        function.argtypes = (ctypes.c_int, ctypes.c_char_p, ctypes.c_int,
                             ctypes.c_char_p, ctypes.c_uint)
        function.restype = ctypes.c_int
        if function(-100 if src_dir_fd is None else src_dir_fd, os.fsencode(staged),
                    -100 if dst_dir_fd is None else dst_dir_fd, os.fsencode(destination), 1) < 0:
            code = ctypes.get_errno()
            raise OSError(code, os.strerror(code), os.fspath(destination))

    def snapshot_file(
        self, source: str | Path, destination: str | Path, *,
        src_dir_fd: int | None = None, dst_dir_fd: int | None = None,
    ) -> None:
        with os.fdopen(os.open(source, os.O_RDONLY | os.O_NOFOLLOW, dir_fd=src_dir_fd), 'rb') as original:
            observed = os.fstat(original.fileno())
            if not stat.S_ISREG(observed.st_mode):
                raise ValueError('A retained snapshot requires a regular source file')
            descriptor = os.open(destination, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW,
                                 0o600, dir_fd=dst_dir_fd)
            try:
                with os.fdopen(descriptor, 'wb') as retained:
                    shutil.copyfileobj(original, retained)
                    self.make_private_descriptor(retained.fileno(), stat.S_IMODE(observed.st_mode))
                    retained.flush()
                    os.fsync(retained.fileno())
            except BaseException:
                os.unlink(destination, dir_fd=dst_dir_fd)
                raise

    def share_file(self, source: Path, destination: Path) -> bool:
        return False  # A byte copy would not deliver the inode sharing this operation promises.


class DarwinPlatform(Platform):
    """libproc exposes microsecond birth times, unlike formatted ps output."""

    def require_watched_procfs(self, refusal: Exception) -> None:
        raise refusal

    class ProcessInfo(ctypes.Structure):
        # External Darwin proc_bsdinfo ABI, from xnu/bsd/sys/proc_info.h.
        _fields_ = [
            (name, ctypes.c_uint32)
            for name in (
                "flags",
                "status",
                "xstatus",
                "pid",
                "ppid",
                "uid",
                "gid",
                "ruid",
                "rgid",
                "svuid",
                "svgid",
                "reserved",
            )
        ] + [
            ("comm", ctypes.c_char * 16),
            ("name", ctypes.c_char * 32),
            ("nfiles", ctypes.c_uint32),
            ("pgid", ctypes.c_uint32),
            ("pjobc", ctypes.c_uint32),
            ("tdev", ctypes.c_uint32),
            ("tpgid", ctypes.c_uint32),
            ("nice", ctypes.c_int32),
            ("start_seconds", ctypes.c_uint64),
            ("start_microseconds", ctypes.c_uint64),
        ]

    def __init__(self):
        self.libproc = ctypes.CDLL("/usr/lib/libproc.dylib", use_errno=True)
        self.libproc.proc_pidinfo.argtypes = (
            ctypes.c_int,
            ctypes.c_int,
            ctypes.c_uint64,
            ctypes.c_void_p,
            ctypes.c_int,
        )
        self.libproc.proc_pidinfo.restype = ctypes.c_int
        self.libproc.proc_listpids.argtypes = (
            ctypes.c_uint32,
            ctypes.c_uint32,
            ctypes.c_void_p,
            ctypes.c_int,
        )
        self.libproc.proc_listpids.restype = ctypes.c_int

    def identity(self, pid: int) -> ProcessIdentity:
        info = self.ProcessInfo()
        size = self.libproc.proc_pidinfo(pid, 3, 0, ctypes.byref(info), ctypes.sizeof(info))
        if size != ctypes.sizeof(info):
            code = ctypes.get_errno()
            if code == 3:  # ESRCH, the actual OS absence result.
                raise ProcessLookupError(pid)
            raise OSError(code, os.strerror(code))
        if info.status == 5:  # SZOMB: exited, awaiting reap.
            raise ProcessLookupError(pid)
        return ProcessIdentity.in_group(
            pid, info.start_seconds * 1_000_000 + info.start_microseconds, info.pgid,
        )

    def started_at(self, identity: ProcessIdentity) -> float:
        return time.monotonic() - (time.time() - identity.start_time / 1_000_000)

    def arguments(self, process: ProcessIdentity) -> tuple[str, ...]:
        raise NotImplementedError(f"{type(self).__name__} does not read process arguments")

    def environment(self, process: ProcessIdentity) -> dict[str, str]:
        raise NotImplementedError(f"{type(self).__name__} does not read process environment")

    def process_name(self, pid: int) -> str:
        raise NotImplementedError(f"{type(self).__name__} does not read process names")

    def members_of_group(self, pgid: int) -> tuple[ProcessIdentity, ...]:
        # proc_listpids returns bytes. Grow until one query fits; never mistake
        # a full buffer for a complete process-group observation.
        capacity = 16
        while True:
            buffer = (ctypes.c_int * capacity)()
            size = self.libproc.proc_listpids(2, pgid, buffer, ctypes.sizeof(buffer))
            if size < 0:
                code = ctypes.get_errno()
                raise OSError(code, os.strerror(code))
            if size < ctypes.sizeof(buffer):
                break
            capacity *= 2
        members = []
        for pid in buffer[: size // ctypes.sizeof(ctypes.c_int)]:
            if pid > 0:
                with suppress(ProcessLookupError):
                    members.append(self.identity(pid))
        return tuple(members)

    def wait_any_exited(
        self, identities: tuple[ProcessIdentity, ...], timeout: float,
    ) -> None:
        with select.kqueue() as pending:
            events = [
                select.kevent(
                    identity.pid, filter=select.KQ_FILTER_PROC,
                    flags=select.KQ_EV_ADD | select.KQ_EV_ONESHOT,
                    fflags=select.KQ_NOTE_EXIT,
                )
                for identity in identities
            ]
            for identity in identities:
                try:
                    current = self.identity(identity.pid)
                except ProcessLookupError:
                    return
                if current != identity:
                    return  # Another incarnation holds the pid: this member exited.
            try:
                returned = pending.control(
                    events, 1, None if math.isinf(timeout) else max(0, timeout),
                )
                for event in returned:
                    if event.flags & select.KQ_EV_ERROR:
                        raise OSError(event.data, os.strerror(event.data))
            except ProcessLookupError:
                return


class UnitActivity(DeclaredFamily, affix="Unit"):
    """systemd's ActiveState of a unit, an external contract decoded once by its spelling."""

    @classmethod
    def ended(cls) -> bool:
        """Whether the unit has stopped running, cleanly or not."""
        return False

    @classmethod
    def serving(cls) -> bool:
        """Whether ``systemctl is-active`` counts the unit as running."""
        return False


class EndedUnit(UnitActivity, declared_name=None):
    @classmethod
    def ended(cls) -> bool:
        return True


class ServingUnit(UnitActivity, declared_name=None):
    @classmethod
    def serving(cls) -> bool:
        return True


class ActiveUnit(ServingUnit): ...


class ReloadingUnit(ServingUnit): ...


class RefreshingUnit(ServingUnit): ...


class ActivatingUnit(UnitActivity): ...


class DeactivatingUnit(UnitActivity): ...


class MaintenanceUnit(UnitActivity): ...


class InactiveUnit(EndedUnit): ...


class FailedUnit(EndedUnit): ...


class ResidentManager(DeclaredFamily, affix="Manager"):
    """What owns this home's units, and a handed-off resident once its launcher is gone: a
    host fact, decoded once, and the only caller of ``systemctl`` and ``systemd-run``.

    Leaving the launcher's process tree is not enough when the launcher is itself a systemd
    unit: ending that unit signals its whole cgroup, setsid and the reparent to init included.
    """

    @staticmethod
    def current(environment: Mapping[str, str] = os.environ) -> ResidentManager:
        """Admit the UID's own home before discovering its manager. Explicit runtime
        directories are never replaced; only an absent address uses the UID's standard
        directory. Both the directory and manager socket must belong to that UID."""
        uid = os.getuid()
        home = Path(pwd.getpwuid(uid).pw_dir).resolve()
        if Path(environment.get("HOME", str(home))).resolve() != home:
            return NoResidentManager()
        runtime = Path(environment.get("XDG_RUNTIME_DIR", f"/run/user/{uid}"))
        if not runtime.is_absolute():
            return NoResidentManager()
        runtime = runtime.resolve()
        try:
            directory = runtime.stat()
            socket = (runtime / "systemd/private").stat()
        except (FileNotFoundError, NotADirectoryError, PermissionError):
            return NoResidentManager()
        if directory.st_uid == uid and socket.st_uid == uid and stat.S_ISSOCK(socket.st_mode):
            return SystemdUserManager(runtime)
        return NoResidentManager()

    def command(self, command: tuple[str, ...]) -> tuple[str, ...]:
        """A host with no manager owns the resident only through its process tree."""
        return command

    def handoff_environment(self, environment: Mapping[str, str]) -> dict[str, str]:
        """Keep the environment required to reach the selected resident manager."""
        return dict(environment)

    def activity(self, unit: str) -> type[UnitActivity]:
        """No manager runs a unit for this home."""
        return InactiveUnit

    def loads(self, unit: str, definition: Path) -> bool:
        """Whether the manager runs ``unit`` from this home's own ``definition``."""
        return False

    def main_pid(self, unit: str, definition: Path) -> int:
        """The process of the unit loaded from ``definition``; zero for any other."""
        return 0

    def listed(self, pattern: str) -> tuple[str, ...]:
        """The names of the active units matching ``pattern``."""
        return ()

    def reload(self) -> None:
        """Load this home's unit definitions; no manager reads a home it does not serve."""

    def install(self, unit: type[SystemdUnit], arguments: tuple[str, ...] = (), *,
                home: Path) -> None:
        """Publish a unit and its declared prerequisites, then load them together."""
        if self.write_unit(unit, arguments, home=home):
            self.reload()

    def required_units(self) -> tuple[type[SystemdUnit], ...]:
        return ()

    def prepare_units(self, *, home: Path) -> None:
        """Install the manager's declared launch prerequisites before releasing a child."""
        for required in self.required_units():
            self.install(required, home=home)

    def write_unit(self, unit: type[SystemdUnit], arguments: tuple[str, ...] = (), *,
                   home: Path) -> bool:
        changed = False
        for required in unit.required_units():
            changed |= self.write_unit(required, home=home)
        destination = unit.unit_file(home)
        definition = unit.unit_text(arguments)
        if not destination.is_file() or destination.read_text(encoding="utf-8") != definition:
            destination.parent.mkdir(parents=True, exist_ok=True)
            destination.write_text(definition, encoding="utf-8")
            changed = True
        return changed

    def control(self, *arguments: str) -> None:
        """Start, stop, enable or disable the manager's units."""
        raise RelationViolationError(
            f"{Path.home()} is not the user's own home, so no user manager belongs to it; "
            f"refused systemctl {' '.join(arguments)}")

    def transient(self, unit: str, command: tuple[str, ...], *, cwd: Path, stdin: Path,
                  stdout: Path, stderr: Path, inherited: tuple[str, ...],
                  assigned: Mapping[str, str], wait: bool) -> None:
        """Run ``command`` as ``unit``, so stopping its caller cannot cut it short; ``wait``
        follows it to its end and raises on its failure. Without a manager only a caller
        that waits can own it."""
        if not wait:
            raise RelationViolationError(
                f"{Path.home()} has no user manager to keep {unit} past its caller")
        environment = {name: os.environ[name] for name in inherited if name in os.environ}
        # As under systemd-run, the unit gets exactly these variables, its import path included.
        with (stdin.open("rb") as given, stdout.open("wb") as answer, stderr.open("wb") as errors,
              SpawnedProcess.launch(command, cwd=cwd, env={**environment, **assigned},
                                    stdio=ConfiguredChildStdio(stdin=given, stdout=answer, stderr=errors),
                                    runtime=RestoredRuntime(Path(command[0]))) as child):
            returncode = child.process.wait()
        if returncode:
            raise subprocess.CalledProcessError(returncode, command)


@dataclass(frozen=True)
class NoResidentManager(ResidentManager): ...


@dataclass(frozen=True)
class SystemdUserManager(ResidentManager):
    """The admitted connection, retained for every command and resident handoff. The user
    manager owns each resident in its own scope; ``systemd-run --scope`` execs in place."""

    runtime_directory: Path

    def command(self, command: tuple[str, ...]) -> tuple[str, ...]:
        return (*AgentsSlice.run_prefix(), "--scope",
                f"--unit=agent-comms-resident-{Id128.mint()}", "--", *command)

    def handoff_environment(self, environment: Mapping[str, str]) -> dict[str, str]:
        return {**environment, "XDG_RUNTIME_DIR": str(self.runtime_directory),
                "DBUS_SESSION_BUS_ADDRESS": f"unix:path={self.runtime_directory}/bus"}

    def required_units(self) -> tuple[type[SystemdUnit], ...]:
        return (AgentsSlice,)

    def shown(self, unit: str, name: str) -> str:
        return subprocess.check_output(
            ("systemctl", "--user", "show", "-p", name, "--value", unit), text=True,
            env=self.handoff_environment(os.environ),
        ).strip()

    def activity(self, unit: str) -> type[UnitActivity]:
        return UnitActivity.member_named(self.shown(unit, "ActiveState"))

    def loads(self, unit: str, definition: Path) -> bool:
        """The manager belongs to the UID, not HOME; the same name loaded from another
        directory is not this home's unit."""
        return (definition.is_file()
                and Path(self.shown(unit, "FragmentPath")).resolve() == definition.resolve())

    def main_pid(self, unit: str, definition: Path) -> int:
        return int(self.shown(unit, "MainPID")) if self.loads(unit, definition) else 0

    def listed(self, pattern: str) -> tuple[str, ...]:
        listed = subprocess.check_output(
            ("systemctl", "--user", "list-units", pattern, "--state=active", "--plain",
             "--no-legend"), text=True, env=self.handoff_environment(os.environ))
        return tuple(line.split()[0] for line in listed.splitlines() if line.strip())

    def reload(self) -> None:
        self.control("daemon-reload")

    def control(self, *arguments: str) -> None:
        subprocess.run(("systemctl", "--user", *arguments), check=True,
                       env=self.handoff_environment(os.environ))

    def transient(self, unit: str, command: tuple[str, ...], *, cwd: Path, stdin: Path,
                  stdout: Path, stderr: Path, inherited: tuple[str, ...],
                  assigned: Mapping[str, str], wait: bool) -> None:
        """systemd-run copies each inherited value from this connection's environment,
        including a runtime directory discovered without an ambient XDG value."""
        self.prepare_units(home=Path.home())
        subprocess.run(
            (*AgentsSlice.run_prefix(), *(("--wait",) if wait else ()),
             f"--unit={unit}", f"--working-directory={cwd}",
             f"--property=StandardInput=file:{stdin}",
             f"--property=StandardOutput=file:{stdout}",
             f"--property=StandardError=file:{stderr}",
             *(f"--setenv={name}" for name in inherited),
             *(f"--setenv={name}={value}" for name, value in assigned.items()), *command),
            check=True, env=self.handoff_environment(os.environ),
        )


class ChildLifetime(DeclaredFamily, affix="Lifetime"):
    """Whether a launched child may outlive the process that launched it."""

    @classmethod
    def is_handoff(cls) -> bool:
        return False

    @classmethod
    def environment(cls, environment: Mapping[str, str]) -> Mapping[str, str]:
        return environment

    @classmethod
    def command(cls, command: tuple[str, ...]) -> tuple[str, ...]:
        """The command the exec gate executes; a child bound to its launcher runs it as given."""
        return command

    @classmethod
    def spawned(cls, process: subprocess.Popen[bytes], descriptor: int) -> SpawnedProcess:
        return SpawnedProcess(process, Platform.current().identity(process.pid))

    @classmethod
    async def spawned_async(cls, process: asyncio.subprocess.Process, descriptor: int) -> AttachedChild:
        return AttachedChild(process, Platform.current().identity(process.pid))

    @classmethod
    @abstractmethod
    def launcher(cls, platform: Platform) -> int:
        """The PID the exec gate binds the child's life to; zero binds none."""


class DiesWithLauncherLifetime(ChildLifetime):
    """Every child by default: a killed launcher cannot leave it running under init.

    The kernel signal follows the launching thread, so the thread that launches
    the child must outlive it, as the event loop and a pool worker's task do.
    """

    @classmethod
    def launcher(cls, platform: Platform) -> int:
        return platform.parent_death_binding()


class OutlivesLauncherLifetime(ChildLifetime):
    """A resident the launcher hands off, such as a worker, a watcher or a bridge."""

    @classmethod
    def is_handoff(cls) -> bool:
        return True

    @classmethod
    def environment(cls, environment: Mapping[str, str]) -> Mapping[str, str]:
        return ResidentManager.current().handoff_environment(environment)

    @classmethod
    def command(cls, command: tuple[str, ...]) -> tuple[str, ...]:
        manager = ResidentManager.current()
        manager.prepare_units(home=Path.home())
        return manager.command(command)

    @staticmethod
    def resident(descriptor: int) -> ProcessIdentity:
        encoded = os.read(descriptor, 64)
        if not encoded:
            raise ChildProcessError("Exec gate exited without handing off its resident")
        return Platform.current().identity(int(encoded))

    @classmethod
    def spawned(cls, process: subprocess.Popen[bytes], descriptor: int) -> SpawnedProcess:
        try:
            identity = cls.resident(descriptor)
        finally:
            returncode = process.wait()
        if returncode != 0:
            raise ChildProcessError("Resident handoff failed")
        return HandedOffProcess(process, identity)

    @classmethod
    async def spawned_async(cls, process: asyncio.subprocess.Process, descriptor: int) -> AttachedChild:
        try:
            identity = await asyncio.to_thread(cls.resident, descriptor)
        finally:
            returncode = await process.wait()
        if returncode != 0:
            raise ChildProcessError("Resident handoff failed")
        return HandedOffAttachedChild(process, identity)

    @classmethod
    def launcher(cls, platform: Platform) -> int:
        return 0


class ChildLaunch:
    def __init__(self, platform: Platform, command: tuple[str, ...],
                 pass_fds: tuple[int, ...], runtime: LaunchRuntime,
                 lifetime: type[ChildLifetime]):
        self.runtime = runtime
        self.platform = platform
        self.command = command
        self.pass_fds = pass_fds
        self.lifetime = lifetime
        self.read_fd, self.write_fd = os.pipe()
        self.error_r, error_w = os.pipe()
        self.error_writer = os.fdopen(error_w, "wb", buffering=0)
        self.identity_r, identity_w = os.pipe()
        self.identity_writer = os.fdopen(identity_w, "wb", buffering=0)

    @property
    def argv(self) -> tuple[str, ...]:
        # The exec gate runs this decoder's code before exec of the selected command.
        return (
            str(LaunchRuntime.running().interpreter),
            "-c",
            _EXEC_GATE,
            str(self.read_fd),
            str(self.error_writer.fileno()),
            str(self.lifetime.launcher(self.platform)),
            str(int(self.lifetime.is_handoff())),
            str(self.identity_writer.fileno()),
            *self.lifetime.command(self.command),
        )

    @property
    def options(self) -> dict:
        return {
            "start_new_session": True,
            "pass_fds": (self.read_fd, self.error_writer.fileno(),
                         self.identity_writer.fileno(), *self.pass_fds),
        }

    def spawned(self, process: subprocess.Popen[bytes]) -> SpawnedProcess:
        self.identity_writer.close()
        return self.lifetime.spawned(process, self.identity_r)

    async def spawned_async(self, process: asyncio.subprocess.Process) -> AttachedChild:
        self.identity_writer.close()
        return await self.lifetime.spawned_async(process, self.identity_r)

    def spawn(
        self,
        *,
        cwd=None,
        env: Mapping[str, str] = INHERITED_ENVIRONMENT,
        stdio: ChildStdio,
    ) -> SpawnedProcess:
        """Hand back the launch handle before the platform allows exec."""
        process = subprocess.Popen(
            self.argv, cwd=cwd,
            env=self.lifetime.environment(self.runtime.child_environment(env)),
            **stdio.streams, **self.options,
        )
        return self.spawned(process)

    async def spawn_async(self, *, cwd, env, stdio: ChildStdio) -> AttachedChild:
        process = await asyncio.create_subprocess_exec(
            self.argv[0], *self.argv[1:], cwd=cwd,
            env=self.lifetime.environment(self.runtime.child_environment(env)),
            **stdio.options, **self.options,
        )
        child = await self.spawned_async(process)
        child._stderr_task = asyncio.create_task(child._drain_stderr())
        return child

    def release(self, identity: ProcessIdentity) -> None:
        self.error_writer.close()
        os.write(self.write_fd, b"G")

    def cancel_before_release(self, identity: ProcessIdentity) -> None:
        # The exec gate has not released user code or spawned descendants.
        with suppress(ProcessLookupError):
            self.platform.send(identity, signal.SIGKILL)

    def verify(self) -> None:
        error = os.read(self.error_r, 64)
        if error:
            code = int(error)
            raise OSError(code, os.strerror(code), self.command[0])

    async def verify_async(self) -> None:
        await _exec_error(self.error_r, self.command[0])

    def close(self) -> None:
        self.error_writer.close()
        self.identity_writer.close()
        for fd in (self.read_fd, self.write_fd, self.error_r, self.identity_r):
            os.close(fd)

    def __enter__(self):
        return self

    def __exit__(self, *_):
        self.close()


class OrderCheckFailedError(ValueError):
    """A completed order check did not prove its expected result."""


class CheckPrinted(DisclosedRecord, DeclaredFamily, affix="Printed"):
    """The count printed by a child, or the absence of an integer."""

    @staticmethod
    def decoded(stdout: bytes) -> CheckPrinted:
        counts = re.findall(r"\d+", stdout.decode(errors="replace"))
        return CountPrinted(int(counts[-1])) if counts else NoIntegerPrinted()

    @abstractmethod
    def unproven(self, command: str, expected: int) -> tuple[str, ...]: ...

    @abstractmethod
    def distance(self, expected: int) -> CheckPrinted: ...

    @abstractmethod
    def plus(self, amount: int) -> CheckPrinted: ...

    @abstractmethod
    def require(self, expected: object) -> None: ...

    @abstractmethod
    def project[T](self, counted: Callable[[int], T],
                   uncounted: Callable[[NoIntegerPrinted], T]) -> T: ...


@dataclass(frozen=True)
class CountPrinted(CheckPrinted):
    count: int

    def distance(self, expected: int) -> CheckPrinted:
        return CountPrinted(abs(self.count - expected))

    def plus(self, amount: int) -> CheckPrinted:
        return CountPrinted(self.count + amount)

    def require(self, expected: object) -> None:
        if self.count:
            raise OrderCheckFailedError(f"The order check is {self.count} away from {expected}.")

    def project[T](self, counted: Callable[[int], T],
                   uncounted: Callable[[NoIntegerPrinted], T]) -> T:
        return counted(self.count)

    def unproven(self, command: str, expected: int) -> tuple[str, ...]:
        return ((f"Check already prints {self.count} before any work: `{command}` proves nothing; "
                 "write a check that fails now",) if self.count == expected else ())


@dataclass(frozen=True)
class NoIntegerPrinted(CheckPrinted):
    def distance(self, expected: int) -> CheckPrinted:
        return self

    def plus(self, amount: int) -> CheckPrinted:
        return self

    def require(self, expected: object) -> None:
        raise OrderCheckFailedError(
            f"The order check cannot prove {expected}: it printed no integer.")

    def project[T](self, counted: Callable[[int], T],
                   uncounted: Callable[[NoIntegerPrinted], T]) -> T:
        return uncounted(self)

    def progress(self, command: str) -> str:
        return f"; check prints no integer: {command}"

    def unproven(self, command: str, expected: int) -> tuple[str, ...]:
        return ("the check printed no integer; use grep -c PATTERN FILE or ... | wc -l",)


class NoCountYetPrinted(NoIntegerPrinted):
    """An unfinished child contributes no count, including digits in partial stdout."""

    def require(self, expected: object) -> None:
        raise ValueError(f"The order check has no count yet; cannot prove {expected}.")

    def unproven(self, command: str, expected: int) -> tuple[str, ...]:
        return (f"the check has no count yet: `{command}` did not finish",)

    def progress(self, command: str) -> str:
        return "; no count yet"


class ChildOutcome(DeclaredFamily, affix="Outcome"):

    def report_shutdown(self, report_timeout: Callable[[], None]) -> None:
        pass

    def report_forced(self, report: Callable[[str], None]) -> None:
        pass

    def report_stopped(self, report: Callable[[], None], stop_exits: frozenset[int]) -> None:
        """Only a signal, or a program's declared stop exit, ends a child as stopped."""

    def fork_failure(self, interrupted_consequence: Callable[[], str]) -> str:
        return ""

    def printed_count(self, stdout: bytes) -> CheckPrinted:
        return NoCountYetPrinted()

    @property
    @abstractmethod
    def summary(self) -> str: ...

    @property
    @abstractmethod
    def successful(self) -> bool: ...

