        return (
            str(LaunchRuntime.running().interpreter),
            "-c",
            "from agent_comms.execution.child_process import ChildCommand; ChildCommand.main()",
            json.dumps(FieldCodec.encode(self)),
        )

    @classmethod
    def main(cls) -> None:
