                  unreadable: Callable[[UnreadableHistory], R],
                  reload: Callable[[ReloadRequired], R]) -> R:
        return deferred(self.error)

    def raised(self) -> T:
        raise self.error


@dataclass(frozen=True)
class ReadReload[T](StoredRead[T]):
