    """What a sidebar stage holds from its last full read."""

    @abstractmethod
    def read(self, stage: SidebarReadStage, request: ObserveSidebar, comms: Comms,
             revision: WireRevision) -> SidebarResult: ...


class NoSidebarCut(HeldSidebarCut):
